option.value:
body {
    font-family: 'Geist Pixel Circle', 'Geist Pixel Square', 'Geist Pixel', monospace !important;
    font-size: 85% !important;
    line-height: 1.6 !important;
    letter-spacing: 0.5px !important;
}

strong, b {
    font-weight: normal !important;
    color: #FF5D9E !important;
    background: rgba(255, 93, 158, 0.1) !important;
    padding: 0px 2px !important;
    border-radius: 4px !important;
}

h1, h2, h3, h4 {
    font-weight: normal !important;
    color: #00E5FF !important; 
    text-shadow: 2px 2px 0px #005F73 !important; 
}

h1 { font-size: 1.35em !important; margin-top: 1.2em !important; margin-bottom: 0.5em !important; }
h2 { font-size: 1.15em !important; margin-top: 1.0em !important; margin-bottom: 0.4em !important; }
h3 { font-size: 1.00em !important; margin-top: 0.9em !important; margin-bottom: 0.3em !important; }
h4 { font-size: 0.90em !important; margin-top: 0.8em !important; margin-bottom: 0.3em !important; }

ul {
    list-style-type: disc !important;
}
ul li::marker {
    color: #00E5FF !important;
    font-size: 1.1em !important;
}

ol li::marker {
    color: #FF5D9E !important;
    font-weight: normal !important;
}


li {
    padding-left: 5px !important;
    margin-bottom: 0.3em !important;
}
